
#include <bits/stdc++.h>
using namespace std;using V=array<unsigned char,7>;
bool le(V const&a,V const&b,int n){for(int i=0;i<n;i++)if(a[i]>b[i])return 0;return 1;}
vector<V> prune(vector<V>x,int n){sort(x.begin(),x.end(),[&](V const&a,V const&b){int A=0,B=0;for(int i=0;i<n;i++)A+=a[i],B+=b[i];return A!=B?A<B:a<b;});x.erase(unique(x.begin(),x.end()),x.end());vector<V>o;for(auto h:x){bool d=0;for(auto g:o)if(le(g,h,n)){d=1;break;}if(!d)o.push_back(h);}return o;}
int main(int ac,char**av){if(ac!=4)return 2;int n=stoi(av[1]);ifstream f(av[2]);ofstream o(av[3]);string l;long long S=0,C=0,HN=0;map<pair<int,int>,long long>cnt;while(getline(f,l)){stringstream ss(l);int m;ss>>m;vector<int>M(m);for(int&i:M)ss>>i;S++;vector<V>col(m);V deg{};for(int c=0;c<m;c++)for(int i=0;i<n;i++){col[c][i]=(M[c]>>i)&1;deg[i]+=col[c][i];}V up{};for(int i=0;i<n;i++)up[i]=deg[i]?deg[i]-1:0;for(int k=2;k<=m-2;k++){C++;vector<V>U;function<void(int,int,V)>rec=[&](int st,int q,V u){if(!q){U.push_back(u);return;}for(int c=st;c<=m-q;c++){auto v=u;for(int i=0;i<n;i++)v[i]+=col[c][i];rec(c+1,q-1,v);}};V z{};rec(0,k,z);vector<V>X{z};for(auto u:U){vector<V>Y;for(auto h:X){bool bad=0;for(int i=0;i<n;i++)if(h[i]>u[i]){bad=1;break;}if(bad)Y.push_back(h);else for(int i=0;i<n;i++)if(u[i]+1<=up[i]){auto g=h;g[i]=u[i]+1;Y.push_back(g);}}X=prune(move(Y),n);if(X.empty())break;}for(auto h:X){o<<m<<" "<<k;for(int a:M)o<<" "<<a;o<<" |";for(int i=0;i<n;i++)o<<int(h[i]);o<<"\n";}HN+=X.size();cnt[{m,k}]+=X.size();}}cerr<<"systems "<<S<<" cases "<<C<<" holes "<<HN<<"\n";for(auto z:cnt)cerr<<z.first.first<<" "<<z.first.second<<" "<<z.second<<"\n";}
